#include "pattern_project_adapter.h"
#include <string.h>
#define PREFIX 20u
typedef struct { fm1_project_adapter *a; uint8_t prefix[PREFIX]; } writer;
typedef struct { fm1_project_adapter *a; } reader;
static int overlaps(const void *a,size_t n,const void *b,size_t m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return n&&m&&(x<=y?y-x<n:x-y<m);}
static int good(const fm1_project_adapter_ops *o,fm1_project_adapter *a,int loading){
 const void *p[9]; size_t n[9]; unsigned i,j;
 if(!o||!a||!a->work||!a->work->pattern||!a->work->session||!a->session||!a->previous||!a->live||!a->previous_live||!a->sector||!a->arena||!a->arena_capacity||!o->quiescent||!o->capture||!o->validate||!o->restore||!o->export_bank||!o->can_adopt||!o->adopt||!o->restore_pattern||!o->quiescent(o->context))return 0;
 p[0]=a->work->pattern;n[0]=sizeof *a->work->pattern;p[1]=a->work->session;n[1]=FM1_PROJECT_SESSION;p[2]=a->session;n[2]=FM1_PROJECT_SESSION;p[3]=a->previous;n[3]=FM1_PROJECT_SESSION;p[4]=a->live;n[4]=sizeof *a->live;p[5]=a->previous_live;n[5]=sizeof *a->previous_live;p[6]=a->sector;n[6]=PFS_SECTOR;p[7]=a;n[7]=sizeof *a;p[8]=a->work;n[8]=sizeof *a->work;
 for(i=0;i<9;i++){if(overlaps(p[i],n[i],a->arena,a->arena_capacity))return 0;if(a->work->arena&&overlaps(p[i],n[i],a->work->arena,a->work->arena_capacity))return 0;for(j=0;j<i;j++)if(overlaps(p[i],n[i],p[j],n[j])&&!(((i==3||i==2)&&j==1&&p[i]==p[j])||(loading&&i==4&&j==0&&p[i]==p[j])||(!loading&&i==5&&j==4&&p[i]==p[j])))return 0;}return 1;}
static int source(void *ctx,uint32_t off,void *out,uint32_t n){writer *w=ctx;uint8_t *p=out;uint32_t take;if(off<PREFIX){take=PREFIX-off;if(take>n)take=n;memcpy(p,w->prefix+off,take);p+=take;off+=take;n-=take;}return n?fm1_project_source_read(&w->a->source,off-PREFIX,p,n):0;}
static int from_store(void *ctx,uint32_t off,void *out,uint32_t n){reader *r=ctx;return pfs_reader_read_at(&r->a->reader,off+PREFIX,out,n,r->a->sector);}
int fm1_project_adapter_save(const pfs_store *store,uint32_t id,const char *name,const fm1_project_adapter_ops *o,fm1_project_adapter *a){writer w;size_t n;int rc;if(!store||id>12||!name||!good(o,a,0))return PFS_INVALID;for(n=0;n<FM1_PROJECT_NAME_BYTES&&name[n];n++)if((unsigned char)name[n]<32||(unsigned char)name[n]>126)return PFS_INVALID;if(!n||n>=FM1_PROJECT_NAME_BYTES)return PFS_INVALID;memset(&w,0,sizeof w);w.a=a;memcpy(w.prefix,"FPA1",4);memcpy(w.prefix+4,name,n);if(id==12){if(a->current_slot< -1||a->current_slot>11)return PFS_INVALID;w.prefix[17]=(uint8_t)(a->current_slot+1);}if(!o->capture(a->session,FM1_PROJECT_SESSION)||!o->export_bank(o->context,&a->bank,a->live,&a->song))return PFS_INVALID;rc=fm1_project_source_init(&a->source,a->session,&a->bank,a->live,&a->song,o->validate,o->context,a->work);if(rc==FM1_PROJECT_FULL)return PFS_FULL;if(rc!=FM1_PROJECT_OK)return PFS_INVALID;{size_t total=0;unsigned i;for(i=0;i<FM1_PATTERN_COUNT;i++)if(i!=a->bank.active){if(a->source.length[i]>a->arena_capacity-total)return PFS_FULL;total+=a->source.length[i];}}if(!o->quiescent(o->context))return PFS_INVALID;return pfs_save_stream(store,id,a->source.total+PREFIX,source,&w,a->sector);}
int fm1_project_adapter_save_initial(const pfs_store *store,const fm1_project_adapter_ops *o,fm1_project_adapter *a){writer w;int rc;if(!store||!good(o,a,1)||a->bank.used!=1||a->bank.active!=0||a->song.used!=1||a->song.active!=0||a->live!=a->work->pattern)return PFS_INVALID;memset(&w,0,sizeof w);w.a=a;memcpy(w.prefix,"FPA1WORKING",11);a->current_slot=-1;rc=fm1_project_source_init(&a->source,a->session,&a->bank,a->live,&a->song,o->validate,o->context,a->work);if(rc==FM1_PROJECT_FULL)return PFS_FULL;if(rc!=FM1_PROJECT_OK||!o->quiescent(o->context))return PFS_INVALID;return pfs_save_stream(store,12,a->source.total+PREFIX,source,&w,a->sector);}
int fm1_project_adapter_load(const pfs_store *store,uint32_t id,char name[FM1_PROJECT_NAME_BYTES],const fm1_project_adapter_ops *o,fm1_project_adapter *a){reader r;uint8_t prefix[PREFIX];unsigned i;int rc;if(!store||id>12||!name||!good(o,a,1)||!a->work->arena||!a->work->arena_capacity)return PFS_INVALID;if(!o->export_bank(o->context,&a->bank,a->previous_live,&a->song)||overlaps(a->arena,a->arena_capacity,a->bank.arena,a->bank.capacity)||overlaps(a->work->arena,a->work->arena_capacity,a->bank.arena,a->bank.capacity)||(a->work->arena!=a->arena&&overlaps(a->work->arena,a->work->arena_capacity,a->arena,a->arena_capacity))||(a->work->arena==a->arena&&a->arena_capacity>a->work->arena_capacity))return PFS_INVALID;rc=pfs_reader_open(store,id,&a->reader,a->sector);if(rc)return rc;if(a->reader.length<=PREFIX||pfs_reader_read_at(&a->reader,0,prefix,PREFIX,a->sector)||memcmp(prefix,"FPA1",4)||prefix[PREFIX-1]||prefix[PREFIX-2]||prefix[17]>12||(id!=12&&prefix[17]))return PFS_INVALID;for(i=0;i<FM1_PROJECT_NAME_BYTES&&prefix[4+i];i++)if(prefix[4+i]<32||prefix[4+i]>126)return PFS_INVALID;if(!i||i==FM1_PROJECT_NAME_BYTES)return PFS_INVALID;for(;i<FM1_PROJECT_NAME_BYTES;i++)if(prefix[4+i])return PFS_INVALID;r.a=a;rc=fm1_project_decode_stream(from_store,&r,a->reader.length-PREFIX,o->validate,o->context,a->work,a->session,&a->bank,a->arena,a->arena_capacity,a->live,&a->song);if(rc==FM1_PROJECT_FULL)return PFS_FULL;if(rc!=FM1_PROJECT_OK||!o->can_adopt(o->context,&a->bank,a->live,&a->song)||!o->capture(a->previous,FM1_PROJECT_SESSION)||!o->quiescent(o->context))return PFS_INVALID;if(!o->restore(a->session,FM1_PROJECT_SESSION)){if(!o->restore(a->previous,FM1_PROJECT_SESSION)||!o->restore_pattern(o->context,a->previous_live))return FM1_PROJECT_ROLLBACK_FAILED;return PFS_INVALID;}if(!o->adopt(o->context,&a->bank,a->live,&a->song)){if(!o->restore(a->previous,FM1_PROJECT_SESSION)||!o->restore_pattern(o->context,a->previous_live))return FM1_PROJECT_ROLLBACK_FAILED;return PFS_INVALID;}memcpy(name,prefix+4,FM1_PROJECT_NAME_BYTES);a->current_slot=id==12?(int)prefix[17]-1:(int)id;return PFS_OK;}
